begin;
set local search_path=public,extensions;
select plan(31);
select ok((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'catalog_%' and c.relkind='r'),'RLS em todas as tabelas do catálogo');
select ok(not has_table_privilege('authenticated','private.catalog_resources','SELECT'),'Sem leitura direta de recursos');
select ok(not has_table_privilege('authenticated','private.catalog_service_versions','UPDATE'),'Sem edição direta de versões');
select ok(not has_function_privilege('anon','public.list_catalog(uuid,uuid,text,text,uuid)','EXECUTE'),'Anônimo não executa leitura');
select ok(not has_function_privilege('service_role','public.publish_catalog_service(uuid,uuid,jsonb,uuid,integer)','EXECUTE'),'Service role sem porta operacional');
select ok(not has_function_privilege('authenticated','private.catalog_audit(uuid,uuid[],text,uuid,text)','EXECUTE'),'Helper de auditoria fechado');
select ok((select bool_and(proconfig @> array['search_path=""']) from pg_proc where proname in ('save_catalog_resource','publish_catalog_service','set_catalog_window','catalog_availability')),'Definers com search_path vazio');
create temp table catalog_fixture(k text primary key,id uuid);
grant all on catalog_fixture to authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
set local role authenticated;
insert into catalog_fixture values('resource',public.save_catalog_resource('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','{"kind":"professional","name":"Profissional pgTAP","units":[{"unit_id":"10000000-0000-0000-0000-000000000011","location":"Centro","capacity":1}]}'));
select throws_ok($$select * from private.catalog_resources$$,'42501',null,'RLS/grants negam acesso direto');
select throws_ok($$select public.list_catalog('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011')$$,'42501',null,'Tenant cruzado negado');
select throws_ok($$select public.list_catalog('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000012')$$,'42501',null,'Unidade sem escopo negada');
select throws_ok($$select public.list_catalog('10000000-0000-0000-0000-000000000001',null)$$,'42501',null,'Unidade obrigatória');
select throws_ok($$select public.set_catalog_timezone('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Inexistente/Fuso')$$,'22023',null,'IANA inválido recusado');
select lives_ok($$select public.set_catalog_window('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011',(select id from catalog_fixture where k='resource'),'shift','2026-12-01 09:00','2026-12-01 12:00')$$,'Jornada local aceita');
select throws_ok($$select public.set_catalog_window('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011',(select id from catalog_fixture where k='resource'),'shift','2026-12-01 11:00','2026-12-01 13:00')$$,'23P01',null,'Sobreposição recusada');
select lives_ok($$select public.set_catalog_window('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011',(select id from catalog_fixture where k='resource'),'exception','2026-12-01 12:00','2026-12-01 13:00')$$,'Intervalos contíguos aceitos');
select throws_ok($$select public.set_catalog_window('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011',(select id from catalog_fixture where k='resource'),'shift','2026-12-01 12:00','2026-12-01 09:00')$$,'22023',null,'Intervalo invertido recusado');
reset role;
select is((select lower(period) at time zone 'UTC' from private.catalog_windows where resource_id=(select id from catalog_fixture where k='resource') and kind='shift'),'2026-12-01 12:00'::timestamp,'Fuso da unidade convertido a instante UTC');
select throws_ok($$insert into private.catalog_resource_units values('20000000-0000-0000-0000-000000000001',(select id from catalog_fixture where k='resource'),'20000000-0000-0000-0000-000000000011','Centro',1)$$,'23503',null,'Referência composta impede recurso de outra clínica');
select throws_ok($$insert into private.catalog_resource_units values('10000000-0000-0000-0000-000000000001',(select id from catalog_fixture where k='resource'),'10000000-0000-0000-0000-000000000012','Centro',0)$$,'23514',null,'Capacidade positiva obrigatória');
-- Configuração de catálogo é distinta da administração de equipe.
update public.tenant_memberships set role='reception' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='a@example.com');
set local role authenticated;
select lives_ok($$select public.list_catalog('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'Recepção pode consultar');
select throws_ok($$select public.save_catalog_resource('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','{}')$$,'42501',null,'Recepção não configura');
select throws_ok($$select public.catalog_team_options('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'42501',null,'Recepção não consulta seletor administrativo');
reset role;
update public.tenant_memberships set role='clinic_admin' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='a@example.com');
-- Falha de auditoria reverte recurso e atribuições na mesma transação.
create function pg_temp.catalog_fail_audit() returns trigger language plpgsql as $$ begin if new.action='catalog_resource_saved' then raise exception 'Falha injetada' using errcode='P0001'; end if; return new; end $$;
create trigger catalog_fail_audit before insert on public.audit_logs for each row execute function pg_temp.catalog_fail_audit();
set local role authenticated;
select throws_ok($$select public.save_catalog_resource('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','{"kind":"room","name":"Rollback pgTAP","units":[{"unit_id":"10000000-0000-0000-0000-000000000011","location":"Centro","capacity":1}]}')$$,'P0001','Falha injetada','Erro na auditoria aborta gravação');
reset role;
select is((select count(*)::integer from private.catalog_resources where name='Rollback pgTAP'),0,'Nenhum recurso parcial após falha');
drop trigger catalog_fail_audit on public.audit_logs;
update public.tenant_memberships set status='revoked' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='a@example.com');
set local role authenticated;
select throws_ok($$select public.list_catalog('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'42501',null,'Revogação tem efeito com mesmo JWT');
reset role;
update public.tenant_memberships set status='active' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='a@example.com');
update public.tenants set status='suspended' where id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.list_catalog('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'42501',null,'Tenant suspenso negado');
reset role;
update public.tenants set status='active' where id='10000000-0000-0000-0000-000000000001';
update public.tenant_entitlements set enabled=false where tenant_id='10000000-0000-0000-0000-000000000001' and module_key='core';
set local role authenticated;
select throws_ok($$select public.list_catalog('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'42501',null,'Módulo núcleo indisponível negado');
reset role;
select ok(not has_function_privilege('anon','public.save_catalog_resource(uuid,uuid,jsonb,uuid,integer)','EXECUTE'),'Anônimo sem escrita');
select ok(not has_function_privilege('anon','public.set_catalog_window(uuid,uuid,uuid,text,timestamp without time zone,timestamp without time zone,text,uuid)','EXECUTE'),'Anônimo sem jornada');
select ok(not has_column_privilege('authenticated','public.units','timezone','UPDATE'),'Fuso não tem escrita direta');
select ok((select count(*)>0 from public.audit_logs where entity_id=(select id::text from catalog_fixture where k='resource') and action='catalog_resource_saved'),'Auditoria gravada com operação');
select * from finish();
rollback;
